SELECT rr.review_id, rr.essay_id, rr.task_id, rr.batch_task_id, rr.source_review_id, rr.rule_version, rr.reviewer_type, rr.reviewer_id, rr.model_version, rr.start_time, rr.end_time, rr.total_score, rr.status, rr.error_msg, rr.retry_count, rr.create_time, rr.is_deleted, e.title AS essay_title FROM review_record rr LEFT JOIN essay e ON rr.essay_id = e.essay_id WHERE rr.is_deleted = 0
AND rr.status = #{status}
AND rr.reviewer_type = #{reviewerType}
ORDER BY rr.create_time DESC

SELECT rr.review_id, rr.essay_id, rr.task_id, rr.batch_task_id, rr.source_review_id, rr.rule_version, rr.reviewer_type, rr.reviewer_id, rr.model_version, rr.start_time, rr.end_time, rr.total_score, rr.status, rr.error_msg, rr.retry_count, rr.create_time, e.title AS essay_title, e.submit_type AS submit_type FROM review_record rr LEFT JOIN essay e ON rr.essay_id = e.essay_id WHERE rr.is_deleted = 0
AND e.user_id = #{userId}
AND rr.essay_id = #{essayId}
AND rr.status = #{status}
AND rr.reviewer_type = #{reviewerType}
ORDER BY rr.create_time DESC

